// Recurring transaction helpers, shared by the API and the UI.
//
// A recurring transaction is stored as a single row (the "template"): its own
// date is the first occurrence, and the following ones are generated by
// repeatedly adding the period, exactly like the stats / predictions APIs do
// (see getNextOccurrence in app/api/stats/route.ts). Keep both in sync.
import { addDays, addMonths, addWeeks, addYears, format, parseISO } from 'date-fns';

export type RecurrenceType = 'daily' | 'weekly' | 'biweekly' | 'monthly' | 'bimonthly' | 'quarterly' | 'yearly';

export const RECURRENCE_LABELS: Record<RecurrenceType, string> = {
  daily: 'Quotidien',
  weekly: 'Hebdomadaire',
  biweekly: 'Toutes les 2 semaines',
  monthly: 'Mensuel',
  bimonthly: 'Tous les 2 mois',
  quarterly: 'Trimestriel',
  yearly: 'Annuel',
};

/** How many times per month the item occurs on average (to compare everything per month). */
export const PER_MONTH: Record<RecurrenceType, number> = {
  daily: 365.25 / 12,
  weekly: 52.18 / 12,
  biweekly: 26.09 / 12,
  monthly: 1,
  bimonthly: 1 / 2,
  quarterly: 1 / 3,
  yearly: 1 / 12,
};

export function nextOccurrence(date: Date, type: string): Date {
  switch (type) {
    case 'daily': return addDays(date, 1);
    case 'weekly': return addWeeks(date, 1);
    case 'biweekly': return addWeeks(date, 2);
    case 'bimonthly': return addMonths(date, 2);
    case 'quarterly': return addMonths(date, 3);
    case 'yearly': return addYears(date, 1);
    default: return addMonths(date, 1);
  }
}

/**
 * Calendar day of a date column. The API serialises DATE columns as timestamps of
 * local midnight on the server (e.g. "2026-12-02T23:00:00.000Z" for 3 December in
 * Paris), so timestamps are read in local time, like the rest of the app does.
 */
export function toDay(value: string | Date): Date {
  const d = value instanceof Date ? value : value.length === 10 ? parseISO(value) : new Date(value);
  return new Date(d.getFullYear(), d.getMonth(), d.getDate());
}

export const ymd = (d: Date) => format(d, 'yyyy-MM-dd');

/**
 * First occurrence on or after `from`, or null if the series has ended before it.
 * `start` is the template date, `end` the optional recurrence end date (inclusive).
 */
export function firstOccurrenceOnOrAfter(start: string | Date, type: string, from: Date, end?: string | Date | null): Date | null {
  const limit = end ? toDay(end) : null;
  let d = toDay(start);
  const target = toDay(from);
  // Guard against runaway loops (daily series over decades)
  for (let i = 0; i < 20000 && d < target; i++) d = nextOccurrence(d, type);
  if (limit && d > limit) return null;
  return d;
}

/** Every occurrence between `from` and `to` (both inclusive). */
export function occurrencesBetween(start: string | Date, type: string, from: Date, to: Date, end?: string | Date | null): Date[] {
  const out: Date[] = [];
  let d = firstOccurrenceOnOrAfter(start, type, from, end);
  const limit = end ? toDay(end) : null;
  const last = toDay(to);
  while (d && d <= last && (!limit || d <= limit) && out.length < 500) {
    out.push(d);
    d = nextOccurrence(d, type);
  }
  return out;
}
